\copy (SELECT e.channel_id, to_char(e.started_at AT TIME ZONE 'Europe/Moscow', 'YYYY-MM-DD HH24:MI:SS') AS t_start, e.fault_value, (e.ended_at IS NULL) AS open_episode FROM smvu.model_failure_episode e WHERE e.fault_value = ANY(ARRAY['Неисправен','Батарея неисправна','Много неисправных устройств','Не определено']) AND e.model_version = 'lgbm-v3-bag-2026.09.21' AND e.started_at >= '2026-03-20 00:00:00+03' AND e.started_at < '2026-07-01 00:00:00+03' AND (e.ended_at IS NULL OR e.ended_at - e.started_at > make_interval(secs => 3600)) ORDER BY 2, 1) TO STDOUT WITH CSV HEADER
